import React from 'react';
import { Download, X } from 'lucide-react';
import { Button } from '@/components/ui/button';

export default function ExportModal({ isOpen, onClose, beliefs }) {
  if (!isOpen) return null;

  const handleExport = () => {
    const data = beliefs.map(belief => ({
      title: belief.title,
      content: belief.content,
      confidence: belief.confidence,
      created_date: belief.created_date,
      status: belief.status
    }));

    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'beliefs-export.json';
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  };

  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
      <div className="bg-white rounded-lg p-6 w-full max-w-md">
        <div className="flex justify-between items-center mb-4">
          <h2 className="text-xl font-semibold">Export Beliefs</h2>
          <Button variant="ghost" size="icon" onClick={onClose}>
            <X className="h-4 w-4" />
          </Button>
        </div>

        <p className="text-gray-600 mb-6">
          Export {beliefs.length} beliefs as JSON file
        </p>

        <div className="flex gap-3">
          <Button onClick={handleExport} className="flex-1">
            <Download className="h-4 w-4 mr-2" />
            Export
          </Button>
          <Button variant="outline" onClick={onClose} className="flex-1">
            Cancel
          </Button>
        </div>
      </div>
    </div>
  );
}
